import { Command } from "commander";

import { invoke, type Implementation } from "@gooi/exchange";
import { artifact } from "@gooi/kernel/evidence";
import { commands } from "./commands.js";

async function run(edge: Implementation, input: unknown, output = "json") {
  try {
    const { artifact: result } = await invoke(edge, artifact(edge.operation.input, input));

    if (output === "text" && typeof result.value !== "string") throw new Error("Expected text output");

    console.log(output === "text" ? result.value : JSON.stringify(result.value, null, 2));
  } catch(error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

const program = new Command("gooi").description("Gooi's own command: slices and tasks");
const sliceCommands = program.command("slice").description("Track gooi's slices; only one is open at a time");

sliceCommands.command("status").description("Show the open slice, the slices waiting for use, and the done slices").action((options) => run(commands.slice.commands.status, { ...options }));
sliceCommands.command("open").description("Open the next slice. Only one slice can be open at a time; waiting slices don't count.").requiredOption("--title <title>", "Short name for the slice").option("--detail <detail>", "What the slice covers").requiredOption("--done <done>", "When it can be closed, in terms of real use").action((options) => run(commands.slice.commands.open, { ...options }));
sliceCommands.command("close").description("Close a slice with what it was used for: the open one, or a waiting one by number").requiredOption("--used <used>", "What the slice was actually used for").option("--number <number>", "The waiting slice to close; leave out for the open one").action((options) => run(commands.slice.commands.close, { ...options }));
sliceCommands.command("wait").description("Move the open slice to waiting: it's built, and closes when its real use comes").action((options) => run(commands.slice.commands.wait, { ...options }));

const taskCommands = program.command("task").description("Track tasks as Markdown files in tasks/");

taskCommands.command("list").description("List open and done tasks, and any files that can't be read").action((options) => run(commands.task.commands.list, { ...options }));
taskCommands.command("add").description("Add a task as a Markdown file, <name>.md, in the task folder").requiredOption("--title <title>", "One-line title").option("--name <name>", "File name; made from the title when left out").option("--notes <notes>", "Notes written below the title").action((options) => run(commands.task.commands.add, { ...options }));
taskCommands.command("finish").description("Mark a task done, changing only its header").requiredOption("--name <name>", "Task name, or a prefix that matches one task").action((options) => run(commands.task.commands.finish, { ...options }));

const agentCommands = program.command("agent").description("Hand work to an agent; GOOI_AGENT picks its backing (claude or omlx)");

agentCommands.command("tell").description("Tell the agent about work to do, in your own words; it adds the tasks").requiredOption("--text <text>", "What you want, in your own words").action((options) => run(commands.agent.commands.tell, { ...options }));
agentCommands.command("sessions").description("List saved agent sessions").action((options) => run(commands.agent.commands.sessions, { ...options }));
agentCommands.command("show").description("Show the transcript of a saved agent session").requiredOption("--session <session>", "Session ID from agent sessions").action((options) => run(commands.agent.commands.show.edge, { ...options }, "text"));

const roomCommands = program.command("room").description("Talk with agents in a room; @claude or @omlx mentions one, @room mentions all");

roomCommands.command("say").description("Post to a room as the owner; agents you mention with @name answer").requiredOption("--room <room>", "Room name: lowercase letters, digits, dots, dashes and underscores").requiredOption("--text <text>", "Your message; @name mentions an agent and @room mentions everyone").action((options) => run(commands.room.commands.say.edge, { ...options }, "text"));
roomCommands.command("show").description("Show a room's messages").requiredOption("--room <room>", "Room name: lowercase letters, digits, dots, dashes and underscores").action((options) => run(commands.room.commands.show.edge, { ...options }, "text"));
roomCommands.command("replay").description("Re-run a past agent answer from its run record, with another agent's backing or the current instructions; writes nothing to the room").requiredOption("--room <room>", "Room name: lowercase letters, digits, dots, dashes and underscores").option("--answer <answer>", "Which agent answer, counting back from the latest: 1 is the latest (the default)").option("--as <as>", "Which agent's backing answers the replay; defaults to the one that answered").option("--instructions <instructions>", "The instructions to replay with: current (the default) or the ones the answer had").action((options) => run(commands.room.commands.replay.edge, { ...options }, "text"));

const workCommands = program.command("work").description("gooi's tasks and GitHub issues in one query, as Markdown tables");

workCommands.command("all").description("All of gooi's tasks and GitHub issues, open first").action((options) => run(commands.work.commands.all.edge, { ...options }, "text"));
workCommands.command("open").description("gooi's open tasks and open GitHub issues").action((options) => run(commands.work.commands.open.edge, { ...options }, "text"));
workCommands.command("query").description("Query gooi's tasks and GitHub issues with one SQL SELECT; tasks and issues are the tables").requiredOption("--sql <sql>", "One SELECT over tasks (name, title, status, created, finished) and issues (number, title, state, author, labels, assignees, comments, created_at, updated_at, closed_at, url)").action((options) => run(commands.work.commands.query.edge, { ...options }, "text"));
await program.parseAsync();
